insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(548, '모네가스크', '{모나코,스타드 루이 2세,1924년 창단}', $t$<p>AS 모나코는 프랑스 리그에 참가하는 모나코 공국의 구단입니다. 2004년 챔피언스리그 결승에 올랐고, 2016-17 시즌에는 10대의 킬리안 음바페를 앞세워 파리 생제르맹을 제치고 리그 우승을 차지했습니다. 박주영이 2008년부터 활약해 한국 팬들에게도 익숙한 구단입니다.</p><p>토리코리 관전 포인트: 모나코는 젊은 선수를 키워 빅클럽에 파는 구단으로 유명해 선수단 변화가 큽니다. 시즌 초반 경기당 승점과 골득실이 함께 높다면 그해 모나코는 우승 경쟁까지 노려볼 만한 전력입니다.</p>$t$),
(523, '레 공', '{리옹,그루파마 스타디움,1950년 창단}', $t$<p>올랭피크 리옹은 2001-02 시즌부터 리그 1을 7시즌 연속 우승하며 2000년대 프랑스 축구를 지배했습니다. 주니뉴의 마법 같은 프리킥이 상징이던 시절이며, 여자팀 역시 유럽 최강으로 군림했습니다. 2016년 새 경기장으로 옮겼고, 생테티엔과의 론알프 더비는 프랑스에서 가장 격렬한 라이벌전 가운데 하나입니다.</p><p>토리코리 관전 포인트: 리옹은 공격적인 축구로 경기당 득점이 높은 시즌이 많지만 수비 기복이 컸습니다. 무실점 경기 비율이 30%를 넘는지가 상위권 경쟁의 기준이 됩니다.</p>$t$),
(1045, '파리지앵', '{파리,스타드 샤를레티,1969년 창단}', $t$<p>파리 FC는 파리 생제르맹과 같은 도시를 연고로 하는 또 하나의 파리 구단입니다. 오랫동안 하부리그에 머물렀지만 명품 그룹 LVMH를 이끄는 아르노 가문과 레드불의 투자를 받아 성장했고, 2025년 1부 리그로 올라왔습니다. 육상 트랙이 있는 샤를레티 경기장을 홈으로 씁니다.</p><p>토리코리 관전 포인트: 투자를 등에 업은 승격팀은 첫 시즌 적응 속도가 관건입니다. 파리 생제르맹과의 파리 더비 결과와 함께, 원정 경기당 승점이 1점 안팎을 유지하는지 지켜보세요.</p>$t$),
(521, '레 도그', '{릴,스타드 피에르 모루아,1944년 창단}', $t$<p>릴 OSC는 벨기에 국경 가까운 프랑스 북부 도시 릴의 구단입니다. 2010-11 시즌과 2020-21 시즌 리그 1을 우승했는데, 특히 2021년 우승은 파리 생제르맹의 독주를 깬 이변으로 기억됩니다. 지붕을 여닫을 수 있는 스타드 피에르 모루아를 홈으로 씁니다.</p><p>토리코리 관전 포인트: 릴은 단단한 수비와 효율적인 역습으로 승점을 쌓는 팀입니다. 골득실에 비해 승점이 높은 편이라면 릴 특유의 실리적인 축구가 잘 통하고 있다는 뜻입니다.</p>$t$),
(529, '레 루주 에 누아르', '{렌,로아존 파크,1901년 창단}', $t$<p>스타드 렌은 프랑스 서북부 브르타뉴 지방을 대표하는 구단으로, 명품 그룹 케링을 이끄는 피노 가문이 오랫동안 소유하고 있습니다. 유럽에서 손꼽히는 유소년 아카데미를 갖춰 세계적인 선수를 여럿 길러냈고, 2019년 쿠프 드 프랑스 결승에서 파리 생제르맹을 꺾고 우승했습니다.</p><p>토리코리 관전 포인트: 렌은 젊은 선수 비중이 높아 경기력이 좋은 날과 나쁜 날의 차이가 큽니다. 최근 5경기 폼과 시즌 전체 경기당 승점을 비교하면 흐름을 읽기 좋습니다.</p>$t$),
(524, '레 파리지앵', '{파리,파르크 데 프랭스,1970년 창단}', $t$<p>파리 생제르맹은 2011년 카타르 자본에 인수된 뒤 프랑스 리그를 지배해 온 구단입니다. 오랫동안 챔피언스리그 우승에 목말랐지만, 2024-25 시즌 결승에서 인테르를 5-0으로 꺾고 마침내 유럽 정상에 올랐습니다. 2023년 이강인이 합류하면서 한국 팬들에게도 가장 가까운 프랑스 구단이 됐습니다. 마르세유와의 "르 클라시크"는 프랑스 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 리그에서 압도적인 전력을 가진 팀인 만큼 승점보다 실점과 무실점 경기 수가 흐름을 더 잘 보여줍니다. 챔피언스리그 일정이 몰리는 시기의 리그 결과를 따로 보면 로테이션의 영향도 확인할 수 있습니다.</p>$t$),
(532, 'SCO', '{앙제,스타드 레몽 코파,1919년 창단}', $t$<p>앙제 SCO는 프랑스 서부 루아르 지방의 도시 앙제를 연고로 하는 구단입니다. 1950년대 발롱도르 수상자 레몽 코파가 프로 경력을 시작한 곳으로, 홈구장도 그의 이름을 따서 부릅니다. 1부와 2부를 오가며 끈질기게 경쟁하는 팀입니다.</p><p>토리코리 관전 포인트: 앙제처럼 잔류를 목표로 하는 팀은 무득점 경기를 줄이는 것이 가장 큰 과제입니다. 무득점 비율이 30% 아래로 내려가는지 확인해 보세요.</p>$t$),
(576, '르 라싱', '{스트라스부르,스타드 드 라 메노,1906년 창단}', $t$<p>RC 스트라스부르 알자스는 독일 국경과 맞닿은 알자스 지방의 구단으로, 1978-79 시즌 리그 우승을 차지했습니다. 2011년 파산으로 5부 리그까지 떨어졌지만 팬들의 지지 속에 차근차근 올라와 1부로 복귀했습니다. 2023년에는 첼시의 소유주 그룹이 인수해 젊은 선수 중심으로 팀을 꾸리고 있습니다.</p><p>토리코리 관전 포인트: 스트라스부르는 평균 연령이 매우 낮은 선수단으로 빠른 공격을 펼치는 팀입니다. 경기당 득점과 함께 후반 실점이 많지 않은지 보면 젊은 팀의 경기 운영 능력을 가늠할 수 있습니다.</p>$t$),
(535, '레 셰브레', '{르망,MMArena,1985년 창단}', $t$<p>르망 FC는 24시간 내구 자동차 경주로 유명한 도시 르망을 연고로 합니다. 2000년대 리그 1에서 활약했지만, 2013년 재정 문제로 아마추어 리그까지 강등되는 시련을 겪었습니다. 이후 하부리그부터 다시 올라오며 재건에 성공했습니다.</p><p>토리코리 관전 포인트: 긴 공백 끝에 1부에 선 팀은 원정 경기에서 고전하기 쉽습니다. 홈 경기당 승점과 원정 경기당 승점 차이가 크다면 원정 운영이 잔류 경쟁의 과제입니다.</p>$t$),
(519, '로세루아', '{오세르,스타드 아베 데샹,1905년 창단}', $t$<p>AJ 오세르는 인구 3만여 명의 작은 도시 구단이지만, 기 루 감독이 40년 넘게 팀을 이끌며 1995-96 시즌 리그와 쿠프 드 프랑스를 함께 우승하는 더블을 달성했습니다. 뛰어난 유소년 육성으로 에리크 캉토나 등 많은 스타를 배출했습니다.</p><p>토리코리 관전 포인트: 오세르는 홈 관중이 가깝게 둘러싼 작은 경기장에서 강한 팀입니다. 홈 무실점 경기 수와 원정 경기당 실점을 비교하면 잔류 경쟁력을 알 수 있습니다.</p>$t$),
(512, '레 피라트', '{브레스트,스타드 프랑시스 르 블레,1950년 창단}', $t$<p>스타드 브레스트 29는 브르타뉴 지방 서쪽 끝 항구 도시 브레스트의 구단입니다. 2023-24 시즌 리그 3위라는 깜짝 성적을 거두며 구단 역사상 처음으로 챔피언스리그 무대를 밟았습니다. 해적(피라트)이라는 별명처럼 끈질기고 투지 넘치는 축구로 사랑받습니다.</p><p>토리코리 관전 포인트: 브레스트는 적은 예산으로 조직력을 극대화한 팀입니다. 한 골 차 경기의 결과가 순위를 크게 좌우하니, 골득실이 작은데 승점이 높다면 접전을 잘 버티고 있다는 뜻입니다.</p>$t$),
(525, '레 메를뤼', '{로리앙,스타드 뒤 무스투아르,1926년 창단}', $t$<p>FC 로리앙은 브르타뉴 지방 남쪽 항구 도시 로리앙의 구단으로, 대구(메를뤼)를 뜻하는 별명처럼 어업 도시의 정체성을 담고 있습니다. 2002년 쿠프 드 프랑스를 우승했고, 1부와 2부를 오가며 공격적인 축구를 선보여 왔습니다.</p><p>토리코리 관전 포인트: 로리앙은 공격적인 운영 탓에 양팀 득점 경기가 많은 팀입니다. 1부에서 살아남으려면 경기당 실점을 1.5골 아래로 묶는 것이 우선입니다.</p>$t$),
(511, '레 비올레', '{툴루즈,스타디움 드 툴루즈,1970년 창단}', $t$<p>툴루즈 FC는 프랑스 남서부 "장밋빛 도시" 툴루즈를 연고로 하며, 보라색 유니폼 때문에 "레 비올레"라고 불립니다. 2023년 쿠프 드 프랑스 결승에서 낭트를 꺾고 구단 역사상 첫 주요 대회 우승을 차지했습니다. 데이터 분석을 적극 활용하는 운영으로 주목받고 있습니다.</p><p>토리코리 관전 포인트: 툴루즈는 중위권에서 효율적인 축구를 하는 팀입니다. 경기당 득점과 실점이 모두 리그 평균 근처라면, 결국 무승부를 얼마나 승리로 바꾸느냐가 순위를 결정합니다.</p>$t$),
(522, '레 제글롱', '{니스,알리안츠 리비에라,1904년 창단}', $t$<p>OGC 니스는 지중해 휴양 도시 니스의 구단으로, 1950년대에 리그를 네 번 우승한 전통을 갖고 있습니다. 화학 기업 이네오스가 인수한 뒤 유럽대항전에 꾸준히 도전하는 팀으로 자리 잡았습니다. 새끼 독수리(에글롱)라는 별명으로 불립니다.</p><p>토리코리 관전 포인트: 니스는 수비가 단단할 때 좋은 성적을 내 온 팀입니다. 경기당 실점이 1골 아래로 유지되는지가 유럽대항전 진출권 경쟁의 기준이 됩니다.</p>$t$),
(546, '상 에 오르', '{랑스,스타드 볼라르 들렐리스,1906년 창단}', $t$<p>RC 랑스는 프랑스 북부 옛 탄광 도시 랑스의 구단으로, 피와 금을 뜻하는 "상 에 오르"라는 별명을 갖고 있습니다. 도시 인구보다 경기장 수용 인원이 더 많을 만큼 주민 모두가 응원하는 구단으로 유명하며, 1997-98 시즌 리그 우승을 차지했습니다. 2022-23 시즌 리그 2위로 챔피언스리그에 복귀했습니다.</p><p>토리코리 관전 포인트: 볼라르 들렐리스의 응원은 프랑스에서 가장 뜨겁습니다. 랑스의 홈 경기당 승점이 원정보다 크게 높다면 홈 팬의 힘이 성적을 끌어올리고 있다는 뜻입니다.</p>$t$),
(531, '에스탁', '{트루아,스타드 드 로브,1986년 창단}', $t$<p>ES 트루아 AC는 프랑스 북동부 샹파뉴 지방의 도시 트루아를 연고로 하는 구단입니다. 2020년 맨체스터 시티를 소유한 시티 풋볼 그룹이 인수해 네트워크의 일원이 됐으며, 1부와 2부를 오가는 대표적인 "엘리베이터 구단"입니다.</p><p>토리코리 관전 포인트: 트루아는 1부에 오를 때마다 잔류 싸움을 벌여 왔습니다. 시즌 초반 10경기 경기당 승점이 1.0을 넘는지가 잔류의 첫 번째 관문입니다.</p>$t$),
(516, '레 포세앙', '{마르세유,오랑주 벨로드롬,1899년 창단}', $t$<p>올랭피크 드 마르세유는 1993년 프랑스 구단 최초로 챔피언스리그를 우승한 구단입니다. 지중해 항구 도시 마르세유의 열정적인 팬들로 가득 차는 벨로드롬은 프랑스에서 가장 뜨거운 경기장으로 꼽힙니다. 파리 생제르맹과의 "르 클라시크"는 두 도시의 자존심이 걸린 프랑스 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 마르세유는 홈과 원정 성적 차이가 큰 팀으로 알려져 있습니다. 벨로드롬의 홈 무패 기록이 이어지는지, 원정에서 승점을 얼마나 챙기는지를 함께 보세요.</p>$t$),
(533, '르 아크', '{르아브르,스타드 오세안,1872년 창단}', $t$<p>르아브르 AC는 1872년 창단한 프랑스에서 가장 오래된 축구 구단입니다. 노르망디 지방의 항구 도시를 연고로 하며, 뛰어난 유소년 아카데미에서 여러 국가대표 선수를 길러냈습니다. 하늘색과 남색 유니폼은 창단 멤버들이 다닌 영국 대학의 색에서 따왔다고 전해집니다.</p><p>토리코리 관전 포인트: 르아브르는 수비적으로 버티며 승점을 쌓는 경기가 많습니다. 0-0 무승부와 한 골 차 경기가 많은지 보면 팀의 운영 방식이 드러납니다.</p>$t$)
